--
-- Notes:
-- - This imports an index of external evidence files, not the evidence binaries.
-- - document_kind='other' is intentional because the CSV does not establish
--   whether each file is a paper scan or an electronic original.
-- - Individual Storage fields and sha256 remain NULL until a source file is
--   copied into Supabase Storage.
-- - source_record_id is the Money Forward CloudBox file ID.

begin;

insert into accounting.import_files (
  company_id,
  source_system,
  file_kind,
  storage_bucket,
  storage_path,
  original_filename,
  sha256,
  row_count,
  import_metadata
)
select
  c.id,
  'moneyforward_cloudbox',
  'cloudbox_filelist',
  'accounting-imports',
  'moneyforward/cloudbox/all_cloudbox_filelist_20261009_091929.csv',
  'all_cloudbox_filelist_20261009_091929.csv',
  '75be8d9f3458ded10f8619a6e36b9bcfdfb8286a83d326b8962775f2e96f286e',
  918,
  jsonb_build_object(
    'scope','all_files',
    'source','Money Forward CloudBox',
    'downloaded_at_local','2026-10-09T09:19:29+09:00'
  )
from accounting.companies c
where c.name='akmic合同会社'
  and not exists (
    select 1
    from accounting.import_files i
    where i.company_id=c.id
      and i.source_system='moneyforward_cloudbox'
      and i.storage_path='moneyforward/cloudbox/all_cloudbox_filelist_20261009_091929.csv'
  );

with c as (
  select id
  from accounting.companies
  where name='akmic合同会社'
  order by created_at
  limit 1
),
imp as (
  select i.id
  from accounting.import_files i
  join c on c.id=i.company_id
  where i.source_system='moneyforward_cloudbox'
    and i.storage_path='moneyforward/cloudbox/all_cloudbox_filelist_20261009_091929.csv'
  order by i.imported_at
  limit 1
),
src(
  receipt_code,
  transaction_date,
  supplier_name,
  amount,
  document_kind,
  original_filename,
  mime_type,
  source_system,
  source_record_id,
  external_url,
  source_metadata
) as (
