insert into accounting.receipts (
  company_id,
  receipt_code,
  transaction_date,
  supplier_name,
  amount,
  currency,
  document_kind,
  storage_bucket,
  storage_path,
  original_filename,
  mime_type,
  sha256,
  captured_at,
  source_metadata,
  source_system,
  source_record_id,
  external_url,
  import_file_id
)
select
  c.id,
  src.receipt_code,
  src.transaction_date::date,
  src.supplier_name,
  src.amount::numeric,
  'JPY',
  src.document_kind,
  null,
  null,
  src.original_filename,
  src.mime_type,
  null,
  null,
  src.source_metadata,
  src.source_system,
  src.source_record_id,
  src.external_url,
  imp.id
from src
cross join c
cross join imp
on conflict (company_id, source_system, source_record_id)
  where source_record_id is not null
do nothing;

do $$
declare
  v_company_id uuid;
  v_import_file_id uuid;
  v_rows integer;
  v_missing_date integer;
  v_missing_supplier integer;
  v_missing_amount integer;
  v_duplicate_source_ids integer;
begin
  select id into v_company_id
  from accounting.companies
  where name='akmic合同会社'
  order by created_at
  limit 1;

  select id into v_import_file_id
  from accounting.import_files
  where company_id=v_company_id
    and source_system='moneyforward_cloudbox'
    and storage_path='moneyforward/cloudbox/all_cloudbox_filelist_20261009_091929.csv'
  order by imported_at
  limit 1;

  select count(*),
         count(*) filter (where transaction_date is null),
         count(*) filter (where supplier_name is null),
         count(*) filter (where amount is null)
    into v_rows, v_missing_date, v_missing_supplier, v_missing_amount
  from accounting.receipts
  where company_id=v_company_id
    and import_file_id=v_import_file_id
    and source_system='moneyforward_cloudbox';

  select count(*) into v_duplicate_source_ids
  from (
    select source_record_id
    from accounting.receipts
    where company_id=v_company_id
      and source_system='moneyforward_cloudbox'
      and source_record_id is not null
    group by source_record_id
    having count(*) > 1
  ) d;

  if v_rows <> 918 then
    raise exception 'Expected 918 CloudBox receipt index rows, got %', v_rows;
  end if;
  if v_missing_date <> 34 then
    raise exception 'Expected 34 rows without transaction_date, got %', v_missing_date;
  end if;
  if v_missing_supplier <> 73 then
    raise exception 'Expected 73 rows without supplier_name, got %', v_missing_supplier;
  end if;
  if v_missing_amount <> 50 then
    raise exception 'Expected 50 rows without amount, got %', v_missing_amount;
  end if;
  if v_duplicate_source_ids <> 0 then
    raise exception 'Expected 0 duplicate CloudBox source_record_id values, got %', v_duplicate_source_ids;
  end if;
end
$$;

commit;
